create extension if not exists pgcrypto;
create table if not exists public.users_settings (id uuid primary key references auth.users(id) on delete cascade, risk_per_trade numeric(8,4) not null default 0.5 check (risk_per_trade>0 and risk_per_trade<=100), compounding_enabled boolean not null default true, daily_loss_limit_percent numeric(8,4) not null default 3 check (daily_loss_limit_percent>0 and daily_loss_limit_percent<=100), paper_initial_balance numeric(24,8) not null default 1000000 check (paper_initial_balance>=0), trading_mode text not null default 'paper' check (trading_mode in ('paper','live')), bot_enabled boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.trading_accounts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, mode text not null check (mode in ('paper','live')), initial_balance numeric(24,8) not null default 0 check (initial_balance>=0), cash_balance numeric(24,8) not null default 0 check (cash_balance>=0), daily_start_balance numeric(24,8) not null default 0 check (daily_start_balance>=0), updated_at timestamptz not null default now(), unique(user_id,mode));
create table if not exists public.allocated_coins (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, symbol text not null, allocation_percent numeric(8,4) not null check (allocation_percent>0 and allocation_percent<=100), is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,symbol));
create table if not exists public.market_ticks (id bigint generated always as identity primary key, symbol text not null, price numeric(24,8) not null check (price>0), created_at timestamptz not null default now());
create index if not exists market_ticks_symbol_created_idx on public.market_ticks(symbol,created_at desc);
create table if not exists public.forecast_signals (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, mode text not null check (mode in ('paper','live')), symbol text not null, suggested_tp numeric(24,8) not null, suggested_sl numeric(24,8) not null, confidence numeric(8,6) not null check (confidence>=0 and confidence<=1), action text not null default 'hold' check (action in ('buy','hold')), indicators jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists forecast_signals_user_mode_created_idx on public.forecast_signals(user_id,mode,created_at desc);
create table if not exists public.positions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, mode text not null check (mode in ('paper','live')), symbol text not null, entry_price numeric(24,8) not null, tp_price numeric(24,8) not null, sl_price numeric(24,8) not null, exit_price numeric(24,8), quantity numeric(24,12) not null check (quantity>0), status text not null check (status in ('open','closed_tp','closed_sl','closed_manual')), opened_at timestamptz not null default now(), closed_at timestamptz, pnl numeric(24,8) not null default 0, fee numeric(24,8) not null default 0, order_id text, exit_order_id text);
create index if not exists positions_user_mode_status_idx on public.positions(user_id,mode,status);
create index if not exists positions_user_mode_opened_idx on public.positions(user_id,mode,opened_at desc);
create unique index if not exists one_open_position_per_symbol on public.positions(user_id,mode,symbol) where status='open';
create table if not exists public.trade_logs (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, position_id uuid references public.positions(id) on delete set null, mode text not null check (mode in ('paper','live')), action text not null check (action in ('open','tp_hit','sl_hit','manual','compound_adjust')), detail jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists trade_logs_user_created_idx on public.trade_logs(user_id,created_at desc);
create index if not exists trade_logs_position_id_idx on public.trade_logs(position_id);
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path=public as $$ begin new.updated_at=now(); return new; end; $$;
drop trigger if exists users_settings_updated_at on public.users_settings; create trigger users_settings_updated_at before update on public.users_settings for each row execute function public.set_updated_at();
drop trigger if exists trading_accounts_updated_at on public.trading_accounts; create trigger trading_accounts_updated_at before update on public.trading_accounts for each row execute function public.set_updated_at();
drop trigger if exists allocated_coins_updated_at on public.allocated_coins; create trigger allocated_coins_updated_at before update on public.allocated_coins for each row execute function public.set_updated_at();
alter table public.users_settings enable row level security; alter table public.trading_accounts enable row level security; alter table public.allocated_coins enable row level security; alter table public.market_ticks enable row level security; alter table public.forecast_signals enable row level security; alter table public.positions enable row level security; alter table public.trade_logs enable row level security;
drop policy if exists users_settings_owner on public.users_settings; create policy users_settings_owner on public.users_settings for all to authenticated using ((select auth.uid())=id) with check ((select auth.uid())=id);
drop policy if exists trading_accounts_owner on public.trading_accounts; create policy trading_accounts_owner on public.trading_accounts for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
drop policy if exists allocated_coins_owner on public.allocated_coins; create policy allocated_coins_owner on public.allocated_coins for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
drop policy if exists market_ticks_authenticated_read on public.market_ticks; create policy market_ticks_authenticated_read on public.market_ticks for select to authenticated using (true);
drop policy if exists forecast_signals_owner on public.forecast_signals; drop policy if exists forecast_signals_insert_owner on public.forecast_signals; create policy forecast_signals_owner on public.forecast_signals for select to authenticated using ((select auth.uid())=user_id); create policy forecast_signals_insert_owner on public.forecast_signals for insert to authenticated with check ((select auth.uid())=user_id);
drop policy if exists positions_owner on public.positions; drop policy if exists positions_insert_owner on public.positions; drop policy if exists positions_update_owner on public.positions; create policy positions_owner on public.positions for select to authenticated using ((select auth.uid())=user_id); create policy positions_insert_owner on public.positions for insert to authenticated with check ((select auth.uid())=user_id); create policy positions_update_owner on public.positions for update to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
drop policy if exists trade_logs_owner on public.trade_logs; drop policy if exists trade_logs_insert_owner on public.trade_logs; create policy trade_logs_owner on public.trade_logs for select to authenticated using ((select auth.uid())=user_id); create policy trade_logs_insert_owner on public.trade_logs for insert to authenticated with check ((select auth.uid())=user_id);
grant select,insert,update,delete on public.users_settings,public.trading_accounts,public.allocated_coins to authenticated;
grant select on public.market_ticks to authenticated;
grant select,insert on public.forecast_signals,public.trade_logs to authenticated;
grant select,insert,update on public.positions to authenticated;
grant all on public.users_settings,public.trading_accounts,public.allocated_coins,public.forecast_signals,public.positions,public.trade_logs to service_role;
grant select on public.market_ticks to service_role;
alter publication supabase_realtime add table public.positions;
alter publication supabase_realtime add table public.forecast_signals;
